from pathlib import Path
import pandas as pd, numpy as np
ROOT=Path(__file__).resolve().parents[1]; RAW=ROOT/'data/raw'; OUT=ROOT/'data/processed'
def read(n): return pd.read_csv(RAW/f'{n}.csv',low_memory=False)
pay=pd.read_csv(OUT/'payments_canonical.csv',parse_dates=['event_at']); pay['month']=pay.event_at.dt.to_period('M').astype(str)
targets=read('daily_targeting'); targets['target_date']=pd.to_datetime(targets.target_date,errors='coerce'); targets=targets.drop_duplicates('target_id').dropna(subset=['target_date'])
success=pay.loc[pay.effective_recovered_amount>0,['account_id','event_at','effective_recovered_amount']].copy(); success['account_id']=success.account_id.astype(str); targets['account_id']=targets.account_id.astype(str)
matched=targets[['target_id','account_id','target_date','recommended_channel','campaign_id','priority','status']].merge(success,on='account_id',how='left'); matched['days_after_target']=(matched.event_at-matched.target_date).dt.total_seconds()/86400
within=matched.loc[matched.days_after_target.between(0,7)].copy(); outcomes=within.groupby('target_id').agg(payment_within_7d=('effective_recovered_amount','sum')).reset_index()
t=targets[['target_id','account_id','target_date','recommended_channel','campaign_id','priority','status']].merge(outcomes,on='target_id',how='left'); t['payment_within_7d']=t.payment_within_7d.fillna(0); t['converted_7d']=(t.payment_within_7d>0).astype(int)
c=t.groupby('recommended_channel').agg(targets=('target_id','nunique'),accounts=('account_id','nunique'),targets_with_payment_7d=('converted_7d','sum'),observed_payment_amount_7d=('payment_within_7d','sum')).reset_index(); c['observed_conversion_rate_pct']=100*c.targets_with_payment_7d/c.targets; c['interpretation']='Descriptive only; no randomized holdout or causal attribution'; c.to_csv(OUT/'targeting_descriptive_association.csv',index=False)
c=t.groupby(['campaign_id','recommended_channel']).agg(targets=('target_id','nunique'),targets_with_payment_7d=('converted_7d','sum'),observed_payment_amount_7d=('payment_within_7d','sum')).reset_index(); c['observed_conversion_rate_pct']=100*c.targets_with_payment_7d/c.targets; c['interpretation']='Descriptive only; overlapping account exposure and confounding possible'; c.to_csv(OUT/'campaign_descriptive_association.csv',index=False)
a=read('accounts').drop_duplicates('account_id'); a['opened_at']=pd.to_datetime(a.opened_at,errors='coerce'); a['vintage_month']=a.opened_at.dt.to_period('M').astype(str)
ap=pay.loc[pay.effective_recovered_amount>0].groupby('account_id').agg(observed_recovered_amount=('effective_recovered_amount','sum')).reset_index(); v=a.merge(ap,on='account_id',how='left'); v['observed_recovered_amount']=v.observed_recovered_amount.fillna(0); v['ever_paid_in_observed_window']=(v.observed_recovered_amount>0).astype(int)
vm=v.groupby(['vintage_month','risk_segment','loan_type']).agg(accounts=('account_id','nunique'),accounts_with_payment=('ever_paid_in_observed_window','sum'),observed_recovered_amount=('observed_recovered_amount','sum')).reset_index(); vm['observed_payer_share_pct']=100*vm.accounts_with_payment/vm.accounts; vm['caveat']='Unequal observation windows; not a vintage recovery-rate metric'; vm.to_csv(OUT/'account_vintage_metrics.csv',index=False)
g=pd.read_csv(OUT/'golden_dataset_account_month.csv'); weights=a.risk_segment.value_counts(normalize=True); r=g.groupby(['month','risk_segment']).agg(accounts=('account_id','nunique'),recovered_amount=('recovered_amount','sum')).reset_index(); r['amount_per_account']=r.recovered_amount/r.accounts.replace(0,np.nan); r['portfolio_weight']=r.risk_segment.map(weights).fillna(0); r['weighted_component']=r.amount_per_account*r.portfolio_weight
m=r.groupby('month').agg(mix_standardized_amount_per_account=('weighted_component','sum'),observed_total_recovered_amount=('recovered_amount','sum')).reset_index(); m['interpretation']='Mix-standardized amount per account using fixed risk-segment weights; not recovery rate and not causal'; m.to_csv(OUT/'mix_adjusted_descriptive_metrics.csv',index=False)
print('Extended descriptive outputs built.')
